def _identity(path, node):
    return path, id(node)


def _dump(node):
    return stable_ast_dump(node)


def _namespace(tree):
    class Headers(ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            node.body = [ast.Pass()]
            return node

        def visit_AsyncFunctionDef(self, node):
            node.body = [ast.Pass()]
            return node

        def visit_Lambda(self, node):
            node.body = ast.Constant(value=None)
            return node

    return _dump(Headers().visit(copy_ast_fields(tree)))


def _calls(region, spelling):
    return [node for node in ast.walk(region) if isinstance(node, ast.Call) and ast.unparse(node.func) == spelling]


def _one_call(region, spelling):
    matches = _calls(region, spelling)
    return matches[0] if len(matches) == 1 else None


def _keyword(call, name):
    values = [keyword for keyword in call.keywords if keyword.arg == name]
    return values[0] if len(values) == 1 else None


def _expression_matches(node, source):
    return isinstance(node, ast.AST) and _dump(node) == _dump(ast.parse(source, mode="eval").body)


def _statement_matches(node, source):
    return isinstance(node, ast.AST) and _dump(node) == _dump(ast.parse(source).body[0])


def _call_matches(node, spelling, arguments=(), keywords=()):
    return (
        isinstance(node, ast.Call)
        and _expression_matches(node.func, spelling)
        and len(node.args) == len(arguments)
        and all(_expression_matches(actual, expected) for actual, expected in zip(node.args, arguments, strict=True))
        and len(node.keywords) == len(keywords)
        and all(
            actual.arg == name and _expression_matches(actual.value, expected)
            for actual, (name, expected) in zip(node.keywords, keywords, strict=True)
        )
    )


def _entry_signature(node, positional, keyword, *, asynchronous):
    return (
        isinstance(node, ast.AsyncFunctionDef if asynchronous else ast.FunctionDef)
        and not node.args.posonlyargs
        and tuple(argument.arg for argument in node.args.args) == positional
        and tuple(argument.arg for argument in node.args.kwonlyargs) == keyword
        and node.args.vararg is None
        and node.args.kwarg is None
        and not node.args.defaults
        and all(value is None for value in node.args.kw_defaults)
        and not node.decorator_list
        and not node.type_params
    )


def _integrity_guard(node, predicate):
    if not (
        isinstance(node, ast.If)
        and _expression_matches(node.test, predicate)
        and not node.orelse
        and len(node.body) == 1
        and isinstance(node.body[0], ast.Raise)
    ):
        return False
    raised = node.body[0]
    return (
        raised.cause is None
        and isinstance(raised.exc, ast.Call)
        and _expression_matches(raised.exc.func, "AuditIntegrityError")
        and len(raised.exc.args) == 1
        and isinstance(raised.exc.args[0], ast.Constant)
        and type(raised.exc.args[0].value) is str
        and not raised.exc.keywords
    )


def _current_work_links(running, names, current):
    """Independently bind the nominal entry to the actual current SQL reader."""
    work_validation = _one_call(names, "_running")
    context_validation = _one_call(running, "work.validate_context")
    if not (
        _entry_signature(running, ("work",), (), asynchronous=False)
        and len(running.body) == 3
        and _integrity_guard(running.body[0], "type(work) is not RequiredWorkBinding or type(work.running) is not ComposerOperationRunning")
        and _call_matches(context_validation, "work.validate_context", ("work.running.session_operation_context",))
        and isinstance(running.body[1], ast.Expr)
        and running.body[1].value is context_validation
        and _statement_matches(running.body[2], "return work.running")
        and _entry_signature(names, (), ("service", "running", "work"), asynchronous=True)
        and len(names.body) == 6
        and _call_matches(work_validation, "_running", ("work",))
        and _integrity_guard(names.body[0], "_running(work) is not running")
        and _statement_matches(
            names.body[1],
            "before = await _registered(work=work, source=RequiredWorkSource.CONTINUATION_READ_SQL, "
            "operation=lambda: _read_selected(service, running), expected=StoredContinuationSnapshot)",
        )
        and _statement_matches(
            names.body[2], "names = await _read_current_env_names(service._advisor_checkpoint, str(running.claim.session_id))"
        )
        and _statement_matches(
            names.body[3],
            "after = await _registered(work=work, source=RequiredWorkSource.CONTINUATION_READ_SQL, "
            "operation=lambda: _read_selected(service, running), expected=StoredContinuationSnapshot)",
        )
        and _integrity_guard(names.body[4], "before != after")
        and _statement_matches(names.body[5], "return CurrentTitleNames(running, after, names)")
        and _entry_signature(current, (), ("service", "running", "required_work"), asynchronous=True)
        and len(current.body) == 3
        and _statement_matches(current.body[0], "names = await current_title_names(service=service, running=running, work=required_work)")
        and _statement_matches(
            current.body[1],
            "def read() -> CurrentTitleResult:\n"
            "    with locked_session_transaction(_sessions(service)._engine, str(running.claim.session_id)) as conn:\n"
            "        names.require(conn)\n"
            "        return read_title_result_on_connection(conn, running, selected=names.selected, inventory=names)",
        )
        and _statement_matches(
            current.body[2],
            "return await _registered(work=required_work, source=RequiredWorkSource.CONTINUATION_READ_SQL, "
            "operation=read, expected=CurrentTitleResult)",
        )
    ):
        return None
    return work_validation, context_validation


def _entry_references(units):
    """Actual qualified runner/settler uses; arbitrary import aliases stay closed."""
    protected = {
        "elspeth.web.composer.continuation_title_provider." + RUN,
        "elspeth.web.composer.continuation_title_provider." + SETTLE,
    }
    references = set()
    for unit in units:
        module = mint._module(unit)
        if module is None:
            continue
        initial = mint._imports(unit.tree)
        if unit.path == PRODUCER:
            initial.update({name: module + "." + name for name in (RUN, SETTLE)})

        def scan(node, env, *, unit=unit):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
                for value in [
                    *node.args.defaults,
                    *(v for v in node.args.kw_defaults if v is not None),
                    *(node.decorator_list if not isinstance(node, ast.Lambda) else []),
                ]:
                    scan(value, env)
                local = dict(env)
                for formal in [
                    *node.args.posonlyargs,
                    *node.args.args,
                    *node.args.kwonlyargs,
                    *([node.args.vararg] if node.args.vararg else []),
                    *([node.args.kwarg] if node.args.kwarg else []),
                ]:
                    local[formal.arg] = None
                for statement in [node.body] if isinstance(node, ast.Lambda) else node.body:
                    scan(statement, local)
                return
            if isinstance(node, ast.ClassDef):
                for value in [*node.bases, *node.decorator_list, *(k.value for k in node.keywords)]:
                    scan(value, env)
                for statement in node.body:
                    scan(statement, dict(env))
                return
            children = ast.iter_child_nodes(node)
            if isinstance(node, ast.AnnAssign):
                children = iter([node.target, *([node.value] if node.value is not None else [])])
            if isinstance(node, ast.arg):
                return
            for child in children:
                scan(child, env)
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                env.update(mint._imports(ast.Module(body=[node], type_ignores=[])))
            if isinstance(node, (ast.Assign, ast.AnnAssign, ast.NamedExpr)):
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                origin = mint._qualify(node.value, env)
                for target in targets:
                    if isinstance(target, ast.Name):
                        env[target.id] = origin
            if isinstance(node, (ast.Name, ast.Attribute)) and isinstance(node.ctx, ast.Load) and mint._qualify(node, env) in protected:
                references.add(_identity(unit.path, node))

        for statement in unit.tree.body:
            scan(statement, dict(initial))
    return frozenset(references)


def title_provider_local_contracts(units):
    """Return the exact transfer plus mandatory common current-source premises."""
    units = tuple(units)
    index = {}
    for unit in units:
        if unit.path in index:
            return ["TITLE transfer: duplicate source unit " + unit.path], None
        index[unit.path] = unit
    missing = [path for path in SOURCE_PATHS if path not in index]
    if missing:
        return ["TITLE transfer: missing current source " + path for path in missing], None
    selected = {}
    failures = []
    for key, source in CONTRACTS.items():
        path, name = key.split(":", 1)
        unit = index[path]
        if not any(
            isinstance(node, ast.ImportFrom)
            and node.level == 0
            and node.module == "__future__"
            and any(alias.name == "annotations" for alias in node.names)
            for node in unit.tree.body
        ):
            failures.append("TITLE transfer: postponed source annotations changed " + path)
        actual, _ = find(unit.tree, name)
        expected = ast.parse(source).body[0]
        if actual is None or _dump(actual) != _dump(expected):
            failures.append("TITLE transfer: complete current source contract changed " + key)
        else:
            selected[key] = actual
    for path, expected in MODULE_NAMESPACES.items():
        if _namespace(index[path].tree) != expected:
            failures.append("TITLE transfer: evaluated namespace changed " + path)
    origins = []
    for consumer, binding, module in ORIGINS:
        path = "src/" + module.replace(".", "/") + ".py"
        actual, _ = find(index[path].tree, binding)
        imported = import_origin(index[consumer].tree, binding, module, binding)
        if imported is None or actual is None or not owned_origin(index[path].tree, binding, actual):
            failures.append("TITLE transfer: current supplier import/definition changed " + consumer + ":" + binding)
            continue
        statement, alias = imported
        origins.append(
            {
                "binding": binding,
                "source_origin": module + "." + binding,
                "import_statement": _identity(consumer, statement),
                "import_alias": _identity(consumer, alias),
                "supplier_definition": _identity(path, actual),
                "qualification": "CURRENT_SOURCE_ORIGIN_RUNTIME_SUPPLIER_UNKNOWN",
            }
        )
    # Deferred imports in the reviewed custody/SQL paths are real suppliers.
    # Record their exact source nodes too; this never marks their calls pure.
    selected_imports = set()
    for key, region in selected.items():
        consumer = key.split(":", 1)[0]
        for statement in ast.walk(region):
            if not (
                isinstance(statement, ast.ImportFrom)
                and statement.level == 0
                and statement.module is not None
                and statement.module.startswith("elspeth.")
            ):
                continue
            for alias in statement.names:
                pair = _identity(consumer, alias)
                if pair in selected_imports:
                    continue
                selected_imports.add(pair)
                supplier_path = "src/" + statement.module.replace(".", "/") + ".py"
                supplier = index.get(supplier_path)
                definition = None if supplier is None else find(supplier.tree, alias.name)[0]
                origins.append(
                    {
                        "binding": alias.asname or alias.name,
                        "source_origin": statement.module + "." + alias.name,
                        "import_statement": _identity(consumer, statement),
                        "import_alias": pair,
                        "supplier_definition": None if definition is None else _identity(supplier_path, definition),
                        "qualification": "DEFERRED_SOURCE_IMPORT_COMMON_ORIGIN_CLOSURE_REQUIRED",
                    }
                )
    if failures:
        return failures, None
    # There is no production dispatcher calling these entries at the reviewed
    # source. Their guarded entries are qualified; this grants no feature wiring.
    references = _entry_references(units)
    if references:
        return ["TITLE transfer: unqualified runner/settlement caller or callable escape"], None
    settle = selected[PRODUCER + ":" + SETTLE]
    current = selected[PRODUCER + ":read_current_title_result"]
    names = selected[PRODUCER + ":current_title_names"]
    running = selected[PRODUCER + ":_running"]
    reserve = _one_call(settle, "required_work.coordinator.reserve")
    finish = _one_call(settle, "_sessions(service).finish_provider_attempt")
    reads = _calls(settle, "read_current_title_result")
    validation = _current_work_links(running, names, current)
    if validation is None:
        return ["TITLE transfer: actual nominal running/current SQL ownership links changed"], None
    work_validation, context_validation = validation
    # These relationships supplement the complete bodies: only these actual
    # nodes may become a transfer certificate on the same caller-owned trees.
    if (
        not _entry_signature(settle, (), ("service", "running", "required_work"), asynchronous=True)
        or len(settle.body) != 5
        or len(reads) != 2
        or not _call_matches(
            reserve,
            "required_work.coordinator.reserve",
            ("RequiredWorkSource.TITLE_PROVIDER_SETTLEMENT_SQL",),
            (("transition_ordinal", "required_work.transition_ordinal"), ("semantic_ordinal", "6"), ("recurrence_ordinal", "0")),
        )
        or not _call_matches(
            finish,
            "_sessions(service).finish_provider_attempt",
            keywords=(
                ("session_operation_context", "running.session_operation_context"),
                ("call", "current.settlement.audit_call"),
                ("required_work", "sql"),
                ("continuation_title", "current.settlement"),
            ),
        )
        or not _statement_matches(
            settle.body[0], "current = await read_current_title_result(service=service, running=running, required_work=required_work)"
        )
        or not _statement_matches(settle.body[1], "if current.settled:\n    return current")
        or not isinstance(settle.body[2], ast.Assign)
        or len(settle.body[2].targets) != 1
        or not isinstance(settle.body[2].targets[0], ast.Name)
        or settle.body[2].targets[0].id != "sql"
        or not isinstance(settle.body[2].targets[0].ctx, ast.Store)
        or settle.body[2].value is not reserve
        or not isinstance(settle.body[3], ast.Expr)
        or not isinstance(settle.body[3].value, ast.Await)
        or settle.body[3].value.value is not finish
        or not _statement_matches(
            settle.body[4], "return await read_current_title_result(service=service, running=running, required_work=required_work)"
        )
    ):
        return ["TITLE transfer: exact current accounting ticket transfer changed"], None
    pair = _identity(PRODUCER, reserve)
    formal = {argument.arg: argument for argument in settle.args.kwonlyargs}
    all_nodes = {(unit.path, id(node)) for unit in units for node in ast.walk(unit.tree)}
    dependencies = {}
    members = {}
    checked_uses = set()
    function_origins = set()
    class_origins = set()

    def definition_origins(path, name, node):
        qualified = path.removeprefix("src/").removesuffix(".py").replace("/", ".") + "." + name
        if isinstance(node, ast.ClassDef):
            class_origins.add(qualified)
        else:
            function_origins.add(qualified)
        for child in node.body:
            if isinstance(child, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                definition_origins(path, name + "." + child.name, child)

    for key, region in selected.items():
        path, name = key.split(":", 1)
        definition_origins(path, name, region)
        for node in ast.walk(region):
            identity = _identity(path, node)
            if isinstance(node, ast.Call):
                dependencies[identity] = {
                    "unit_path": path,
                    "region": name,
                    "node_id": id(node),
                    "operator_node_id": id(node.func),
                    "operator_ast": _dump(node.func),
                    "qualification": "COMMON_ORIGIN_RECEIVER_EFFECT_PROOF_REQUIRED",
                    "execution_role": "UNCLASSIFIED_COMMON_EXECUTION_ROLE_REQUIRED",
                }
            if isinstance(node, ast.Attribute):
                members[identity] = {
                    "unit_path": path,
                    "region": name,
                    "node_id": id(node),
                    "member_ast": _dump(node),
                    "qualification": "COMMON_SOURCE_RECEIVER_MEMBER_EFFECT_PROOF_REQUIRED",
                }
            if isinstance(node, (ast.Name, ast.Attribute)) and isinstance(node.ctx, ast.Load):
                checked_uses.add(identity)
    source_ids = {_identity(key.split(":", 1)[0], node) for key, node in selected.items()}
    if not ({pair, *source_ids, *checked_uses} <= all_nodes):
        return ["TITLE transfer: source identities do not share the supplied AST"], None
    return [], {
        "reserve_calls": frozenset({pair}),
        "validated_transfer_calls": frozenset({pair}),
        "selected_definitions": frozenset(source_ids),
        "source_origins": tuple(origins),
        "protected_origins": frozenset(function_origins | class_origins),
        "function_origins": frozenset(function_origins),
        "class_origins": frozenset(class_origins),
        # All loads below are evidence, never a blanket use exemption.
        "checked_reference_uses": frozenset(checked_uses),
        "validated_supplier_uses": frozenset(),
        "validated_calls": frozenset(),
        "entry_reference_uses": references,
        "dependencies": tuple(dependencies.values()),
        "receiver_dependencies": tuple(members.values()),
        "reserve_receipts": {
            pair: {
                "owner_definition": _identity(PRODUCER, settle),
                "work_formal": _identity(PRODUCER, formal["required_work"]),
                "running_formal": _identity(PRODUCER, formal["running"]),
                "service_formal": _identity(PRODUCER, formal["service"]),
                "initial_current_read_call": _identity(PRODUCER, reads[0]),
                "already_settled_guard": _identity(PRODUCER, settle.body[1]),
                "reserve_member": _identity(PRODUCER, reserve.func),
                "reserve_receiver": _identity(PRODUCER, reserve.func.value),
                "source_value": _identity(PRODUCER, reserve.args[0]),
                "ordinal_values": tuple(_identity(PRODUCER, keyword.value) for keyword in reserve.keywords),
                "ticket_store": _identity(PRODUCER, settle.body[2].targets[0]),
                "finisher_call": _identity(PRODUCER, finish),
                "finisher_member": _identity(PRODUCER, finish.func),
                "finisher_receiver_sessions_call": _identity(PRODUCER, finish.func.value),
                "required_work_keyword": _identity(PRODUCER, _keyword(finish, "required_work")),
                "required_work_value": _identity(PRODUCER, _keyword(finish, "required_work").value),
                "final_current_read_call": _identity(PRODUCER, reads[1]),
                "current_reader_definition": _identity(PRODUCER, current),
                "work_validation_call": _identity(PRODUCER, work_validation),
                "work_context_validation_call": _identity(PRODUCER, context_validation),
                "qualification": "SAME_AST_CURRENT_TITLE_ACCOUNTING_TRANSFER_COMMON_EFFECTS_REQUIRED",
            }
        },
        "remaining_premises": (
            "UNKNOWN_COMMON_SOURCE_IMPORT_BINDING_CLOSURE",
            "UNKNOWN_CURRENT_SERVICE_RECEIVER_MEMBER_AND_OUTSIDE_EFFECT_CLOSURE",
            "UNKNOWN_SQL_WORKER_LOCK_TRANSACTION_CODEC_AND_DATABASE_EFFECTS",
            "UNKNOWN_CURRENT_RUNNING_BINDING_COORDINATOR_TICKET_CONTEXT_CUSTODY",
            "UNKNOWN_HISTORICAL_DATA_CURRENT_TRANSACTION_CAPABILITY_SEPARATION",
        ),
    }
